),

pcx AS (
  SELECT CONCAT(article_id, "_", sales_uom_cd) AS liam,
    division,
    banner,
    lcl_week_of_year_num,
    lcl_year_num,
    ROUND(SUM(sales_amt),2) AS pcx_sales,
  FROM `ld-ds-bi-analytics-prod.bi_reporting.sl_trans_qlfy_ecom_dly`
  LEFT JOIN `ld-pcx-bia.dim.dates` ON transaction_dt = cal_date
  LEFT JOIN `ld-pcx-bia.dim.stores_flip` st ON st.store_number = LTRIM(site_id,'0')
  WHERE transaction_dt > DATE("2024-01-01") -- REQUIRED to put a transaction_dt filter on
    AND article_acct_assn_grp_cd IN ('01','21') -- ALWAYS use this filter on this table
    AND ecom_ind IN ('4','5') -- PCXPU and PCXD only
    AND article_id LIKE "2%"
  GROUP BY 1,2,3,4,5
),

rtl AS (
  SELECT CONCAT(artcl_num, "_",sl_uom_cd) AS liam,
    division,
    banner,
    lcl_week_of_year_num,
    lcl_year_num,
    ROUND(SUM(prrtd_pstd_sl_amt),2) AS rtl_sales
  FROM `lt-dia-lake-prd-consume.financial_reporting.sales_lcl_store_article_dly`
  LEFT JOIN `ld-pcx-bia.dim.dates` ON trans_dt = cal_date
  LEFT JOIN `ld-pcx-bia.dim.stores_flip` st ON st.store_number = LTRIM(site_num,'0')
  WHERE trans_dt > DATE("2024-01-01") -- REQUIRED TO put a trans_dt filter
    AND artcl_acct_assn_grp_cd IN ('01','21') -- ALWAYS use this filter on this table
    AND artcl_num LIKE "2%"
  GROUP BY 1,2,3,4,5
  )

SELECT liams.liam, 
  artcl_med_desc_en sap_desc,
  mch_3_desc_en AS mch_3, 
  mch_2_desc_en AS mch_2, 
  mch_1_desc_en AS mch_1, 
  mch_0_desc_en AS mch_0, 
  mch_0_cd,
  CONCAT(IFNULL(ah_01_desc_en,""),">",
    IFNULL(ah_02_desc_en,""),">",
    IFNULL(ah_03_desc_en,""),">",
    IFNULL(ah_04_desc_en,""),">",
    IFNULL(ah_05_desc_en,""),">",
    IFNULL(ah_06_desc_en,""),">",
    IFNULL(ah_07_desc_en,""),">",
    IFNULL(ah_08_desc_en,""),">",
    IFNULL(ah_09_desc_en,"")) AS ah_chain,
  ah_cd_max,
  ah_cd_max_val,
  rtl.division, 
  rtl.banner, 
  rtl.lcl_week_of_year_num, 
  rtl.lcl_year_num, 
  IFNULL(pcx_sales,0) AS pcx_sales, rtl_sales
FROM liams
JOIN `lt-dia-lake-prd-consume.product.article_curr` ON SPLIT(liams.liam, "_")[OFFSET(0)] = artcl_num
LEFT JOIN rtl on liams.liam = rtl.liam
LEFT JOIN pcx ON (pcx.liam, pcx.division, pcx.banner, pcx.lcl_week_of_year_num, pcx.lcl_year_num) = (rtl.liam, rtl.division,rtl.banner, rtl.lcl_week_of_year_num, rtl.lcl_year_num)
ORDER BY 3,4,5,6,1,13,12,10,11
